# -*- coding: utf-8 -*-
"""يبني المجموعة الذهبية لاختبار الإعراب واكتشاف الخلاف (gold.jsonl) وورقة مراجعتها (review.md).
المجموعة للقياس فقط: لا تدخل تدريبًا ولا ضبطًا للإعدادات. حقل review يبقى «pending» حتى يراجعها مختص.

الاصطلاح: لا يُعلَّم «خلاف في العامل» العامّ الذي يصدق على كل جملة (رافع المبتدأ والخبر، رافع الفاعل، رافع المضارع،
ناصب المفعول به: الإنصاف م5، م74، م11)؛ ويُعلَّم ما سواه. والمصدر يُذكر فقط إذا تُحقِّق منه (الإنصاف من الفهرس المتحقَّق
بالصفحة المطبوعة، والهمع والمغني مما قُرئ في الشاملة)؛ وما لم يُتحقَّق مصدره يُعلَّم needs_source ولا تُكتب له صفحة."""
import json, os

INSAF = "الإنصاف في مسائل الخلاف"
def insaf(m, vol, page, issue): return {"kind": "عامل", "issue": issue, "source": {"book": INSAF, "masala": m, "vol": vol, "page": page}, "needs_source": False}
def src(book, vol, page, note=None): return {"book": book, "vol": vol, "page": page, **({"note": note} if note else {})}
def wajh(issue, *sources, status=None, roles=None):
    """status: «موثّق» (الوجه منقول بنصه في المصدر)، «موثّق جزئيًّا» (بعض الوجوه لم يوجد)، أو None (لم يُتحقَّق).
    roles: أبواب الكلمة التي يجيزها المصدر؛ ما وافقها من الأدوات لا يُعدّ خطأً في القياس (measure.py)."""
    return {"kind": "وجه", "issue": issue, "source": sources[0] if sources else None, "also": list(sources[1:]),
            "needs_source": not sources, "status": status if sources else "لم يُتحقَّق", "roles": list(roles or [])}

FAIL, CONJ = "فعل وفاعل: فعل ماضٍ مبني على السكون لاتصاله بتاء الفاعل، والتاء ضمير متصل مبني على الضم في محل رفع فاعل", None
G = []
# قسم الآية عند المحلّل المدرَّب (train_irab.split_of): السورة التي رقمها يُختم بـ7 اختبار، وبـ3 تطوير، وما سواهما تدريب.
# فآيات «التدريب» قد حفظها المحلّل، ولا يُقاس عليها تعميمه؛ والقياس الصادق على آيات «الاختبار».
SURA = {"البقرة": 2, "الأعراف": 7, "التوبة": 9, "يونس": 10, "يوسف": 12, "الإسراء": 17, "طه": 20, "فاطر": 35, "الصافات": 37,
        "محمد": 47, "الرحمن": 55, "الطلاق": 65, "الملك": 67, "الأعلى": 87, "القدر": 97, "الزلزلة": 99}
def split_of(ref):
    if not ref:
        return None
    n = SURA[ref.split()[0]]
    return "test" if n % 10 == 7 else "dev" if n % 10 == 3 else "train"
def add(id, genre, text, words, cat, khilaf=(), watch=False, ref=None, note=None):
    assert len(words) == len(text.split()), (id, len(words), len(text.split()))
    G.append({"id": id, "genre": genre, "ref": ref, "parser_split": split_of(ref), "text": text, "category": cat, "parser_watch": watch,
              "words": [{"w": w, "irab": i} for w, i in zip(text.split(), words)], "khilaf": [dict(k, word=k.get("word")) for k in khilaf],
              "note": note, "review": "pending"})

