add("t01", "قرآن", "لِمِثْلِ هَذَا فَلْيَعْمَلِ الْعَامِلُونَ", ["اللام حرف جر مبني على الكسر، ومثل اسم مجرور وعلامة جره الكسرة، وهو مضاف، والجار والمجرور متعلق بـ«يعمل»", "اسم إشارة مبني على السكون في محل جر مضاف إليه", "الفاء حرف مبني على الفتح، واللام لام الأمر حرف جزم مبني على السكون، ويعمل فعل مضارع مجزوم وعلامة جزمه السكون، وحُرّك بالكسر لالتقاء الساكنين", "فاعل مرفوع وعلامة رفعه الواو لأنه جمع مذكر سالم"], "none", watch=True, ref="الصافات 61", note="لام الأمر بعد الفاء؛ وأصلها الكسر فسُكّنت (إعراب النحاس ج3 ص287)")
add("t02", "قرآن", "مَنِ اهْتَدَى فَإِنَّمَا يَهْتَدِي لِنَفْسِهِ", ["اسم شرط جازم مبني على السكون، وحُرّك بالكسر لالتقاء الساكنين، في محل رفع مبتدأ", "فعل ماضٍ مبني على الفتح المقدّر على الألف للتعذر في محل جزم فعل الشرط، وفاعله ضمير مستتر جوازًا تقديره هو", "الفاء رابطة لجواب الشرط، وإنما كافة ومكفوفة", "فعل مضارع مرفوع وعلامة رفعه الضمة المقدّرة على الياء للثقل، وفاعله ضمير مستتر جوازًا تقديره هو، والجملة في محل جزم جواب الشرط", "اللام حرف جر، ونفس اسم مجرور وعلامة جره الكسرة، والهاء ضمير متصل في محل جر مضاف إليه، والجار والمجرور متعلق بـ«يهتدي»"], "ambiguous",
    [dict(wajh("خبر اسم الشرط: جملة الشرط، أو الجواب، أو هما", src("الدر المصون", 2, 17), status="موثّق"), word="مَنِ")], watch=True, ref="الإسراء 15", note="من الشرطية")
add("t03", "قرآن", "خَلَقَ الْمَوْتَ وَالْحَيَاةَ لِيَبْلُوَكُمْ", ["فعل ماضٍ مبني على الفتح، وفاعله ضمير مستتر جوازًا تقديره هو", "مفعول به منصوب وعلامة نصبه الفتحة", "الواو حرف عطف، والحياة اسم معطوف على «الموت» منصوب وعلامة نصبه الفتحة", "اللام لام التعليل حرف جر، ويبلو فعل مضارع منصوب بأن مضمرة جوازًا بعد لام التعليل وعلامة نصبه الفتحة، وفاعله مستتر تقديره هو، والكاف ضمير متصل في محل نصب مفعول به، والميم علامة الجمع، والمصدر المؤول في محل جر باللام، والجار والمجرور متعلق بـ«خلق»"], "none", watch=True, ref="الملك 2", note="واو العطف لا المعية، ولام التعليل لا الأمر")
add("t04", "قرآن", "وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا", ["الواو استئنافية، وإذا ظرف لما يستقبل من الزمان متضمن معنى الشرط مبني على السكون في محل نصب", "فعل ماضٍ مبني للمجهول مبني على الفتح، والجملة في محل جر بإضافة «إذا» إليها", "نائب فاعل مرفوع وعلامة رفعه الضمة", "الفاء رابطة لجواب الشرط، واستمعوا فعل أمر مبني على حذف النون، والواو ضمير متصل في محل رفع فاعل، والألف فارقة", "اللام حرف جر، والهاء ضمير متصل مبني في محل جر، والجار والمجرور متعلق بـ«استمعوا»", "الواو حرف عطف، وأنصتوا فعل أمر مبني على حذف النون، والواو ضمير متصل في محل رفع فاعل، والألف فارقة"], "none", ref="الأعراف 204")
