here = os.path.dirname(os.path.abspath(__file__))
with open(os.path.join(here, "gold.jsonl"), "w", encoding="utf-8") as f:
    for g in G:
        f.write(json.dumps(g, ensure_ascii=False) + "\n")

# ورقة المراجعة
L = ["# مراجعة المجموعة الذهبية: الإعراب ومواضع الخلاف", "",
     f"{len(G)} جملة (منها {sum(g['parser_split'] == 'test' for g in G)} آيات من سور لم يُدرَّب عليها المحلّل). لكل جملة: صحّح الإعراب كلمةً كلمة، ثم تصنيفها (لا خلاف / خلاف موثّق / ملتبس)، ثم المصادر.",
     "اكتب ملاحظتك تحت «مراجعتك». ما لم تُعلّق عليه يُعدّ مقبولًا.", "",
     "**اصطلاح:** الخلاف العامّ في رافع المبتدأ والخبر والفاعل والمضارع وناصب المفعول به لا يُعلَّم، لأنه يصدق على كل جملة.",
     "**المصادر:** صفحات الإنصاف متحقَّق منها في فهرس المسائل؛ والهمع والمغني مما قُرئ في الشاملة. «يحتاج مصدرًا» = لم تُكتب له صفحة.",
     "**الوجوه:** كل وجه معلَّم بحاله: [موثّق] قُرئ نصه في الصفحة المذكورة؛ [موثّق جزئيًّا] وُجد بعض الوجوه دون بعض. الأرقام بالجزء والصفحة المطبوعة كما في الشاملة.", ""]
cat_ar = {"none": "لا خلاف", "khilaf": "خلاف موثّق", "ambiguous": "ملتبس / أوجه"}
for g in G:
    L.append(f"## {g['id']} · {g['genre']}{' · ' + g['ref'] if g['ref'] else ''}{' (خارج تدريب المحلّل)' if g['parser_split'] == 'test' else ''} · {cat_ar[g['category']]}{' · ⚠️ يُراقَب فيها المحلّل' if g['parser_watch'] else ''}")
    L.append(f"\n**{g['text']}**\n")
    for w in g["words"]:
        L.append(f"- **{w['w']}**: {w['irab']}")
    for k in g["khilaf"]:
        s = k["source"]
        cite = lambda a: f"{a['book']}{(' ج' + str(a['vol'])) if a['vol'] else ''} ص{a['page']}" + (f" ({a['note']})" if a.get("note") else "")
        where = (f"{s['book']}، المسألة {s['masala']}، ج{s['vol']} ص{s['page']}" if s and s.get("masala") else cite(s) if s else "يحتاج مصدرًا")
        if k.get("status") and s:
            where = f"[{k['status']}] " + where
        extra = "؛ وانظر " + "، ".join(cite(a) for a in k.get("also", [])) if k.get("also") else ""
        L.append(f"- 🔸 **{k['kind']}** في «{k['word']}»: {k['issue']} — {where}{extra}")
    if g["note"]:
        L.append(f"- ملاحظة: {g['note']}")
    L.append("\n**مراجعتك:** \n")
with open(os.path.join(here, "review.md"), "w", encoding="utf-8") as f:
    f.write("\n".join(L))
